public class FirstUniqueTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("firstUnique({apple, banana, apple, cherry})", "banana",
                FirstUnique.firstUnique(new String[]{"apple", "banana", "apple", "cherry"}));
        check("firstUnique({a, b, a, b, c})", "c",
                FirstUnique.firstUnique(new String[]{"a", "b", "a", "b", "c"}));
        check("first element already unique", "solo",
                FirstUnique.firstUnique(new String[]{"solo", "dup", "dup"}));
        check("single element", "only",
                FirstUnique.firstUnique(new String[]{"only"}));
        check("all duplicated returns null", null,
                FirstUnique.firstUnique(new String[]{"x", "y", "x", "y"}));
        check("empty array returns null", null,
                FirstUnique.firstUnique(new String[0]));
        check("case sensitive counting", "Dog",
                FirstUnique.firstUnique(new String[]{"dog", "Dog", "dog"}));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
